SELECT clock_timestamp() AS db_at,m.product_id,m.movement_type,m.storage_location_id,m.warehouse_id,count(*) AS rows,sum(m.quantity_delta) AS delta,min(m.created_at) AS first_at,max(m.created_at) AS last_at,count(m.outbound_shipment_line_id) AS outbound_line_refs,count(m.inventory_count_line_id) AS inventory_count_refs,count(m.transfer_group_id) AS transfer_refs FROM inventory_movements m WHERE m.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND m.product_id IN (SELECT DISTINCT p.product_id FROM fbs_order_products p JOIN fbs_orders o ON o.id=p.order_id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon') AND m.quantity_delta<0 AND m.movement_type<>'fbs_shipment' AND m.created_at >= (SELECT min(o.created_at) FROM fbs_orders o WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon') GROUP BY m.product_id,m.movement_type,m.storage_location_id,m.warehouse_id ORDER BY m.product_id,m.movement_type LIMIT 100
